def comps_tile(tile):
 h=len(tile);w=len(tile[0]); seen=set(); out=[]
 for i in range(h):
  for j in range(w):
   c=tile[i][j]
   if c==5 or (i,j) in seen: continue
   stack=[(i,j)]; seen.add((i,j)); comp=[]
   while stack:
    y,x=stack.pop(); comp.append((y,x))
    for dy in (-1,0,1):
     for dx in (-1,0,1):
      q=(y+dy,x+dx)
      if 0<=q[0]<h and 0<=q[1]<w and q not in seen and tile[q[0]][q[1]]==c:
       seen.add(q); stack.append(q)
   out.append((c,len(comp),comp))
 return out
